#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::panic,
    reason = "test code: panicking on failure is intentional"
)]

use std::collections::HashMap;

use proptest::prelude::*;
use vn_runtime::{
    Parser,
    script::{
        expr::{EvalContext, Expr, evaluate},
        parser::{extract_audio_src, extract_img_src, parse_dialogue, parse_transition_args},
    },
    state::VarValue,
};

// ── Test Context ────────────────────────────────────────────────────────

struct Ctx {
    vars: HashMap<String, VarValue>,
}

impl EvalContext for Ctx {
    fn get_var(&self, name: &str) -> Option<&VarValue> {
        self.vars.get(name)
    }
}

// ── Strategies ──────────────────────────────────────────────────────────

fn arb_var_value() -> impl Strategy<Value = VarValue> {
    prop_oneof![
        any::<i64>().prop_map(VarValue::Int),
        any::<f64>().prop_map(VarValue::Float),
        any::<bool>().prop_map(VarValue::Bool),
        "\\PC{0,50}".prop_map(|s| VarValue::String(s)),
    ]
}

fn arb_leaf_expr() -> impl Strategy<Value = Expr> {
    prop_oneof![
        any::<i64>().prop_map(Expr::int),
        any::<bool>().prop_map(Expr::bool),
        "\\PC{0,20}".prop_map(|s| Expr::string(s)),
        "[a-z_][a-z0-9_]{0,10}".prop_map(|s| Expr::var(s)),
    ]
}

fn arb_expr() -> impl Strategy<Value = Expr> {
    arb_leaf_expr().prop_recursive(4, 32, 2, |inner| {
        prop_oneof![
            (inner.clone(), inner.clone()).prop_map(|(a, b)| Expr::eq(a, b)),
            (inner.clone(), inner.clone()).prop_map(|(a, b)| Expr::not_eq(a, b)),
            (inner.clone(), inner.clone()).prop_map(|(a, b)| Expr::and(a, b)),
            (inner.clone(), inner.clone()).prop_map(|(a, b)| Expr::or(a, b)),
            inner.clone().prop_map(Expr::not),
        ]
    })
}

// ── Property Tests ──────────────────────────────────────────────────────

proptest! {
    /// 任意 UTF-8 输入不应让 parser panic
    #[test]
    fn parser_never_panics(input in "\\PC{0,500}") {
        let mut parser = Parser::new();
        let _ = parser.parse("fuzz", &input);
    }

    /// 任意构造的表达式树在空 context 下求值不 panic（可以返回 Err，但不 panic）
    #[test]
    fn expr_eval_never_panics(expr in arb_expr()) {
        let ctx = Ctx { vars: HashMap::new() };
        let _ = evaluate(&expr, &ctx);
    }

    /// 字面量表达式求值后类型不变
    #[test]
    fn literal_preserves_type(value in arb_var_value()) {
        let expr = Expr::Literal(value.clone());
        let ctx = Ctx { vars: HashMap::new() };
        let result = evaluate(&expr, &ctx).unwrap();
        match (&value, &result) {
            (VarValue::Int(_), VarValue::Int(_))
            | (VarValue::Float(_), VarValue::Float(_))
            | (VarValue::Bool(_), VarValue::Bool(_))
            | (VarValue::String(_), VarValue::String(_)) => {}
            _ => panic!("type changed: {value:?} → {result:?}"),
        }
    }

    /// float 相等性：相同值总是相等
    #[test]
    fn float_self_equality(f in prop::num::f64::NORMAL) {
        let ctx = Ctx { vars: HashMap::new() };
        let expr = Expr::eq(
            Expr::Literal(VarValue::Float(f)),
            Expr::Literal(VarValue::Float(f)),
        );
        let result = evaluate(&expr, &ctx).unwrap();
        prop_assert_eq!(result, VarValue::Bool(true));
    }

    /// 变量 roundtrip：set 后 get 返回相同值
    #[test]
    fn var_roundtrip(
        name in "[a-z_][a-z0-9_]{0,15}",
        value in arb_var_value(),
    ) {
        let mut vars = HashMap::new();
        vars.insert(name.clone(), value.clone());
        let ctx = Ctx { vars };
        let expr = Expr::var(&name);
        let result = evaluate(&expr, &ctx).unwrap();
        prop_assert_eq!(result, value);
    }

    /// helper 函数任意输入不 panic
    #[test]
    fn helpers_never_panic(input in "\\PC{0,200}") {
        let _ = extract_img_src(&input);
        let _ = extract_audio_src(&input);
        let _ = parse_transition_args(&input);
        let _ = parse_dialogue(&input);
    }

    /// 对话解析：合法格式时 speaker 和 content 正确分离
    #[test]
    fn dialogue_roundtrip(
        speaker in "[\\p{L}\\p{N}]{1,10}",
        content in "[\\p{L}\\p{N}\\s]{1,30}",
    ) {
        let full_colon = format!("{speaker}：\"{content}\"");
        if let Some((parsed_speaker, parsed_content)) = parse_dialogue(&full_colon) {
            prop_assert_eq!(parsed_speaker.as_deref(), Some(speaker.as_str()));
            prop_assert_eq!(parsed_content, content.clone());
        }

        let half_colon = format!("{speaker}:\"{content}\"");
        if let Some((parsed_speaker, parsed_content)) = parse_dialogue(&half_colon) {
            prop_assert_eq!(parsed_speaker.as_deref(), Some(speaker.as_str()));
            prop_assert_eq!(parsed_content, content);
        }
    }
}

