1	//! # 表达式模块
2	//!
3	//! 定义脚本逻辑系统的表达式类型和求值器。
4	//!
5	//! ## 设计原则
6	//!
7	//! - 表达式是**无副作用**的纯函数
8	//! - 求值是**确定性**的，不依赖 IO 或真实时间
9	//! - 错误信息带**行号/上下文**
10	//!
11	//! ## 支持的类型
12	//!
13	//! - `String`: 字符串
14	//! - `Bool`: 布尔值
15	//!
16	//! ## 支持的操作
17	//!
18	//! - 比较: `==`, `!=`
19	//! - 逻辑: `and`, `or`, `not`
20	
21	use serde::{Deserialize, Serialize};
22	
23	use crate::state::VarValue;
24	
25	/// 表达式 AST 节点
26	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
27	pub enum Expr {
28	    /// 字面量值
29	    Literal(VarValue),
30	
31	    /// 变量引用
32	    ///
33	    /// 变量名不包含 `$` 前缀
34	    Variable(String),
35	
36	    /// 相等比较
37	    Eq(Box<Expr>, Box<Expr>),
38	
39	    /// 不等比较
40	    NotEq(Box<Expr>, Box<Expr>),
41	
42	    /// 逻辑与
43	    And(Box<Expr>, Box<Expr>),
44	
45	    /// 逻辑或
46	    Or(Box<Expr>, Box<Expr>),
47	
48	    /// 逻辑非
49	    Not(Box<Expr>),
50	}
51	
52	impl Expr {
53	    /// 创建字符串字面量
54	    pub fn string(s: impl Into<String>) -> Self {
55	        Self::Literal(VarValue::String(s.into()))
56	    }
57	
58	    /// 创建布尔字面量
59	    pub fn bool(b: bool) -> Self {
60	        Self::Literal(VarValue::Bool(b))
61	    }
62	
63	    /// 创建整数字面量
64	    pub fn int(n: i64) -> Self {
65	        Self::Literal(VarValue::Int(n))
66	    }
67	
68	    /// 创建变量引用
69	    pub fn var(name: impl Into<String>) -> Self {
70	        Self::Variable(name.into())
71	    }
72	
73	    /// 创建相等比较
74	    pub fn eq(left: Expr, right: Expr) -> Self {
75	        Self::Eq(Box::new(left), Box::new(right))
76	    }
77	
78	    /// 创建不等比较
79	    pub fn not_eq(left: Expr, right: Expr) -> Self {
80	        Self::NotEq(Box::new(left), Box::new(right))
81	    }
82	
83	    /// 创建逻辑与
84	    pub fn and(left: Expr, right: Expr) -> Self {
85	        Self::And(Box::new(left), Box::new(right))
86	    }
87	
88	    /// 创建逻辑或
89	    pub fn or(left: Expr, right: Expr) -> Self {
90	        Self::Or(Box::new(left), Box::new(right))
91	    }
92	
93	    /// 创建逻辑非
94	    #[expect(
95	        clippy::should_implement_trait,
96	        reason = "Expr::not is a constructor, not std::ops::Not"
97	    )]
98	    pub fn not(expr: Expr) -> Self {
99	        Self::Not(Box::new(expr))
100	    }
101	}
102	
103	/// 表达式求值错误
104	#[derive(Debug, Clone, PartialEq)]
105	pub enum EvalError {
106	    /// 变量未定义
107	    UndefinedVariable { name: String },
108	
109	    /// 类型不匹配
110	    TypeMismatch {
111	        expected: &'static str,
112	        actual: String,
113	        context: String,
114	    },
115	}
116	
117	impl std::fmt::Display for EvalError {
118	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
119	        match self {
120	            EvalError::UndefinedVariable { name } => {
121	                write!(f, "变量 '{name}' 未定义")
122	            }
123	            EvalError::TypeMismatch {
124	                expected,
125	                actual,
126	                context,
127	            } => {
128	                write!(f, "类型不匹配: 期望 {expected}，实际 {actual} ({context})")
129	            }
130	        }
131	    }
132	}
133	
134	impl std::error::Error for EvalError {}
135	
136	/// 表达式求值上下文
137	///
138	/// 提供变量查找能力
139	pub trait EvalContext {
140	    /// 获取变量值
141	    fn get_var(&self, name: &str) -> Option<&VarValue>;
142	}
143	
144	/// 对表达式求值
145	///
146	/// # 参数
147	///
148	/// - `expr`: 要求值的表达式
149	/// - `ctx`: 求值上下文（提供变量查找）
150	///
151	/// # 返回
152	///
153	/// 求值结果（`VarValue`）或错误
154	pub fn evaluate(expr: &Expr, ctx: &impl EvalContext) -> Result<VarValue, EvalError> {
155	    match expr {
156	        Expr::Literal(value) => Ok(value.clone()),
157	
158	        Expr::Variable(name) => ctx
159	            .get_var(name)
160	            .cloned()
161	            .ok_or_else(|| EvalError::UndefinedVariable { name: name.clone() }),
162	
163	        Expr::Eq(left, right) => {
164	            let left_val = evaluate(left, ctx)?;
165	            let right_val = evaluate(right, ctx)?;
166	            Ok(VarValue::Bool(values_equal(&left_val, &right_val)))
167	        }
168	
169	        Expr::NotEq(left, right) => {
170	            let left_val = evaluate(left, ctx)?;
171	            let right_val = evaluate(right, ctx)?;
172	            Ok(VarValue::Bool(!values_equal(&left_val, &right_val)))
173	        }
174	
175	        Expr::And(left, right) => {
176	            let left_val = evaluate(left, ctx)?;
177	            let left_bool = to_bool(&left_val, "and 左操作数")?;
178	
179	            // 短路求值
180	            if !left_bool {
181	                return Ok(VarValue::Bool(false));
182	            }
183	
184	            let right_val = evaluate(right, ctx)?;
185	            let right_bool = to_bool(&right_val, "and 右操作数")?;
186	            Ok(VarValue::Bool(right_bool))
187	        }
188	
189	        Expr::Or(left, right) => {
190	            let left_val = evaluate(left, ctx)?;
191	            let left_bool = to_bool(&left_val, "or 左操作数")?;
192	
193	            // 短路求值
194	            if left_bool {
195	                return Ok(VarValue::Bool(true));
196	            }
197	
198	            let right_val = evaluate(right, ctx)?;
199	            let right_bool = to_bool(&right_val, "or 右操作数")?;
200	            Ok(VarValue::Bool(right_bool))
201	        }
202	
203	        Expr::Not(inner) => {
204	            let inner_val = evaluate(inner, ctx)?;
205	            let inner_bool = to_bool(&inner_val, "not 操作数")?;
206	            Ok(VarValue::Bool(!inner_bool))
207	        }
208	    }
209	}
210	
