1	//! # 表达式解析器
2	//!
3	//! 递归下降表达式解析器，支持变量、字面量、比较和逻辑运算。
4	
5	use crate::{error::ParseError, script::Expr};
6	
7	/// 解析表达式字符串
8	///
9	/// 支持的语法:
10	/// - 字面量: `"string"`, `true`, `false`
11	/// - 变量: `$var_name`
12	/// - 比较: `$var == "value"`, `$var != "value"`
13	/// - 逻辑: `expr and expr`, `expr or expr`, `not expr`
14	/// - 括号: `(expr)`
15	pub fn parse_expression(input: &str, line_number: usize) -> Result<Expr, ParseError> {
16	    let input = input.trim();
17	    if input.is_empty() {
18	        return Err(ParseError::InvalidLine {
19	            line: line_number,
20	            message: "空表达式".to_string(),
21	        });
22	    }
23	
24	    // 使用简单的递归下降解析器
25	    let mut parser = ExprParser::new(input, line_number);
26	    let expr = parser.parse_or()?;
27	    parser.skip_whitespace()?;
28	    if !parser.remaining().is_empty() {
29	        return Err(ParseError::InvalidLine {
30	            line: line_number,
31	            message: format!("表达式末尾存在无法解析的内容: '{}'", parser.remaining()),
32	        });
33	    }
34	    Ok(expr)
35	}
36	
37	/// 表达式解析器
38	struct ExprParser<'a> {
39	    input: &'a str,
40	    pos: usize,
41	    line_number: usize,
42	}
43	
44	impl<'a> ExprParser<'a> {
45	    fn new(input: &'a str, line_number: usize) -> Self {
46	        Self {
47	            input,
48	            pos: 0,
49	            line_number,
50	        }
51	    }
52	
53	    fn remaining(&self) -> &str {
54	        &self.input[self.pos..]
55	    }
56	
57	    fn stalled_parse_error(&self, context: &str) -> ParseError {
58	        ParseError::InvalidLine {
59	            line: self.line_number,
60	            message: format!("{context} 时解析器未前进，已停止以避免死循环"),
61	        }
62	    }
63	
64	    fn advance_bytes(&mut self, byte_count: usize, context: &str) -> Result<(), ParseError> {
65	        let old_pos = self.pos;
66	        self.pos = self
67	            .pos
68	            .checked_add(byte_count)
69	            .ok_or_else(|| ParseError::InvalidLine {
70	                line: self.line_number,
71	                message: format!("{context} 时解析器位置溢出"),
72	            })?;
73	        if self.pos <= old_pos {
74	            return Err(self.stalled_parse_error(context));
75	        }
76	        Ok(())
77	    }
78	
79	    fn skip_whitespace(&mut self) -> Result<(), ParseError> {
80	        while self.pos < self.input.len() {
81	            let c = self.input[self.pos..]
82	                .chars()
83	                .next()
84	                .expect("invariant: non-empty slice when pos < input.len()");
85	            if c.is_whitespace() {
86	                self.advance_bytes(c.len_utf8(), "跳过空白")?;
87	            } else {
88	                break;
89	            }
90	        }
91	        Ok(())
92	    }
93	
94	    fn peek_char(&self) -> Option<char> {
95	        self.input[self.pos..].chars().next()
96	    }
97	
98	    fn consume_char(&mut self) -> Result<Option<char>, ParseError> {
99	        let Some(c) = self.peek_char() else {
100	            return Ok(None);
101	        };
102	        self.advance_bytes(c.len_utf8(), "消费字符")?;
103	        Ok(Some(c))
104	    }
105	
106	    fn starts_with_keyword(&self, keyword: &str) -> bool {
107	        let remaining = self.remaining().to_lowercase();
108	        if remaining.starts_with(&keyword.to_lowercase()) {
109	            // 确保后面是空白或结束
110	            let after = &self.input[self.pos + keyword.len()..];
111	            after.is_empty()
112	                || after.starts_with(char::is_whitespace)
113	                || after.starts_with('(')
114	                || after.starts_with(')')
115	        } else {
116	            false
117	        }
118	    }
119	
120	    fn consume_keyword(&mut self, keyword: &str) -> Result<(), ParseError> {
121	        self.advance_bytes(keyword.len(), &format!("消费关键字 '{keyword}'"))?;
122	        self.skip_whitespace()
123	    }
124	
125	    /// 解析 or 表达式（最低优先级）
126	    fn parse_or(&mut self) -> Result<Expr, ParseError> {
127	        let mut left = self.parse_and()?;
128	
129	        loop {
130	            self.skip_whitespace()?;
131	            if self.starts_with_keyword("or") {
132	                self.consume_keyword("or")?;
133	                let right = self.parse_and()?;
134	                left = Expr::or(left, right);
135	            } else {
136	                break;
137	            }
138	        }
139	
140	        Ok(left)
141	    }
142	
143	    /// 解析 and 表达式
144	    fn parse_and(&mut self) -> Result<Expr, ParseError> {
145	        let mut left = self.parse_not()?;
146	
147	        loop {
148	            self.skip_whitespace()?;
149	            if self.starts_with_keyword("and") {
150	                self.consume_keyword("and")?;
151	                let right = self.parse_not()?;
152	                left = Expr::and(left, right);
153	            } else {
154	                break;
155	            }
156	        }
157	
158	        Ok(left)
159	    }
160	
161	    /// 解析 not 表达式
162	    fn parse_not(&mut self) -> Result<Expr, ParseError> {
163	        self.skip_whitespace()?;
164	        if self.starts_with_keyword("not") {
165	            self.consume_keyword("not")?;
166	            let expr = self.parse_not()?;
167	            Ok(Expr::not(expr))
168	        } else {
169	            self.parse_comparison()
170	        }
171	    }
172	
173	    /// 解析比较表达式
174	    fn parse_comparison(&mut self) -> Result<Expr, ParseError> {
175	        let left = self.parse_primary()?;
176	
177	        self.skip_whitespace()?;
178	
179	        // 检查比较运算符
180	        if self.remaining().starts_with("==") {
181	            self.advance_bytes(2, "消费比较运算符 '=='")?;
182	            self.skip_whitespace()?;
183	            let right = self.parse_primary()?;
184	            Ok(Expr::eq(left, right))
185	        } else if self.remaining().starts_with("!=") {
186	            self.advance_bytes(2, "消费比较运算符 '!='")?;
187	            self.skip_whitespace()?;
188	            let right = self.parse_primary()?;
189	            Ok(Expr::not_eq(left, right))
190	        } else {
191	            Ok(left)
192	        }
193	    }
194	
195	    /// 解析基本表达式
196	    fn parse_primary(&mut self) -> Result<Expr, ParseError> {
197	        self.skip_whitespace()?;
198	
199	        let c = self.peek_char().ok_or_else(|| ParseError::InvalidLine {
200	            line: self.line_number,
201	            message: "表达式意外结束".to_string(),
202	        })?;
203	
204	        match c {
205	            // 括号
206	            '(' => {
207	                self.consume_char()?;
208	                let expr = self.parse_or()?;
209	                self.skip_whitespace()?;
210	                if self.peek_char() != Some(')') {
211	                    return Err(ParseError::InvalidLine {
212	                        line: self.line_number,
213	                        message: "缺少右括号 ')'".to_string(),
214	                    });
215	                }
216	                self.consume_char()?;
217	                Ok(expr)
218	            }
219	
220	            // 变量
221	            '$' => {
222	                self.consume_char()?;
223	                let name = self.parse_identifier()?;
224	                Ok(Expr::var(name))
225	            }
226	
227	            // 字符串字面量
228	            '"' => {
229	                let s = self.parse_string_literal('"')?;
230	                Ok(Expr::string(s))
231	            }
232	            '\'' => {
233	                let s = self.parse_string_literal('\'')?;
234	                Ok(Expr::string(s))
235	            }
236	
237	            // 布尔字面量或数字
238	            _ => {
239	                if self.starts_with_keyword("true") {
240	                    self.consume_keyword("true")?;
241	                    Ok(Expr::bool(true))
242	                } else if self.starts_with_keyword("false") {
243	                    self.consume_keyword("false")?;
244	                    Ok(Expr::bool(false))
245	                } else if c.is_ascii_digit() || c == '-' {
246	                    // 尝试解析数字
247	                    let num = self.parse_number()?;
248	                    Ok(Expr::int(num))
249	                } else {
250	                    Err(ParseError::InvalidLine {
251	                        line: self.line_number,
252	                        message: format!("无法解析表达式，意外字符: '{c}'"),
253	                    })
254	                }
255	            }
256	        }
257	    }
258	
259	    /// 解析标识符
260	    ///
261	    /// 支持普通标识符 `[a-zA-Z0-9_]+` 以及持久变量命名空间 `persistent.[a-zA-Z0-9_]+`。
262	    fn parse_identifier(&mut self) -> Result<String, ParseError> {
263	        let start = self.pos;
264	
265	        while self.pos < self.input.len() {
266	            let c = self.input[self.pos..]
267	                .chars()
268	                .next()
269	                .expect("invariant: non-empty slice when pos < input.len()");
270	            // 允许 '.' 仅用于 persistent. 前缀：如果当前累积的 token 恰好是 "persistent" 且下一个字符是 '.'，继续
271	            if c == '.' {
272	                let so_far = &self.input[start..self.pos];
273	                if so_far == "persistent" {
274	                    self.advance_bytes(c.len_utf8(), "解析持久变量命名空间")?;
275	                    continue;
276	                }
277	                break;
278	            }
279	            if c.is_alphanumeric() || c == '_' {
280	                self.advance_bytes(c.len_utf8(), "解析标识符")?;
281	            } else {
282	                break;
283	            }
284	        }
285	
286	        if self.pos == start {
287	            return Err(ParseError::InvalidLine {
288	                line: self.line_number,
289	                message: "期望标识符".to_string(),
290	            });
291	        }
292	
293	        Ok(self.input[start..self.pos].to_string())
294	    }
295	
296	    /// 解析字符串字面量
297	    fn parse_string_literal(&mut self, quote: char) -> Result<String, ParseError> {
298	        self.consume_char()?; // 消费开始引号
299	        let start = self.pos;
300	
301	        while self.pos < self.input.len() {
302	            let c = self.input[self.pos..]
303	                .chars()
304	                .next()
305	                .expect("invariant: non-empty slice when pos < input.len()");
306	            if c == quote {
307	                let s = self.input[start..self.pos].to_string();
308	                self.consume_char()?; // 消费结束引号
309	                return Ok(s);
310	            }
311	            self.advance_bytes(c.len_utf8(), "解析字符串字面量")?;
312	        }
313	
314	        Err(ParseError::InvalidLine {
315	            line: self.line_number,
316	            message: format!("字符串字面量未闭合，缺少 '{quote}'"),
317	        })
318	    }
319	
320	    /// 解析数字
321	    fn parse_number(&mut self) -> Result<i64, ParseError> {
322	        let start = self.pos;
323	
324	        // 处理负号
325	        if self.peek_char() == Some('-') {
326	            self.consume_char()?;
327	        }
328	
329	        while self.pos < self.input.len() {
330	            let c = self.input[self.pos..]
331	                .chars()
332	                .next()
333	                .expect("invariant: non-empty slice when pos < input.len()");
334	            if c.is_ascii_digit() {
335	                self.advance_bytes(c.len_utf8(), "解析数字")?;
336	            } else {
337	                break;
338	            }
339	        }
340	
341	        let num_str = &self.input[start..self.pos];
342	        num_str.parse::<i64>().map_err(|_| ParseError::InvalidLine {
343	            line: self.line_number,
344	            message: format!("无法解析数字: '{num_str}'"),
345	        })
346	    }
347	}
348	
349	#[cfg(test)]
350	mod tests {
351	    use super::*;
352	
353	    #[test]
354	    fn test_advance_bytes_rejects_zero_progress() {
355	        let mut parser = ExprParser::new("abc", 7);
356	        let err = parser.advance_bytes(0, "测试推进保护").unwrap_err();
357	        assert!(matches!(err, ParseError::InvalidLine { .. }));
358	        assert!(format!("{err}").contains("未前进"));
359	    }
360	}
