//! 控制流指令解析：goto、callScript、conditional、set、wait、choice table

use super::{
    super::{
        expr_parser::parse_expression,
        helpers::{extract_quoted_path, is_table_separator, starts_with_ignore_case},
    },
    Phase2Parser,
};
use crate::{
    error::ParseError,
    script::{
        Expr,
        ast::{ChoiceOption, ConditionalBranch, ScriptNode},
    },
};

impl Phase2Parser {
    /// 解析 set 指令
    ///
    /// 语法: `set $var = value`
    pub(super) fn parse_set_var(
        &self,
        line: &str,
        line_number: usize,
    ) -> Result<Option<ScriptNode>, ParseError> {
        let content = line[4..].trim();

        let eq_pos = content
            .find('=')
            .ok_or_else(|| ParseError::MissingParameter {
                line: line_number,
                command: "set".to_string(),
                param: "赋值符号 '='".to_string(),
            })?;

        let var_part = content[..eq_pos].trim();
        let value_part = content[eq_pos + 1..].trim();

        let var_name = var_part
            .strip_prefix('$')
            .ok_or_else(|| ParseError::InvalidLine {
                line: line_number,
                message: format!("变量名必须以 '$' 开头，实际: '{var_part}'"),
            })?;

        if var_name.is_empty() {
            return Err(ParseError::MissingParameter {
                line: line_number,
                command: "set".to_string(),
                param: "变量名".to_string(),
            });
        }

        let is_valid = if let Some(bare) = var_name.strip_prefix("persistent.") {
            !bare.is_empty() && bare.chars().all(|c| c.is_alphanumeric() || c == '_')
        } else {
            var_name.chars().all(|c| c.is_alphanumeric() || c == '_')
        };
        if !is_valid {
            return Err(ParseError::InvalidLine {
                line: line_number,
                message: format!(
                    "变量名格式无效。普通变量名只能含字母、数字和下划线；持久变量须为 persistent.<name> 格式，实际: '{var_name}'"
                ),
            });
        }

        let value = parse_expression(value_part, line_number)?;

        Ok(Some(ScriptNode::SetVar {
            name: var_name.to_string(),
            value,
        }))
    }

    /// 解析条件块
    pub(super) fn parse_conditional(
        &mut self,
        lines: &[(String, usize)],
        start_line: usize,
    ) -> Result<Option<ScriptNode>, ParseError> {
        if lines.is_empty() {
            return Ok(None);
        }

        let last_line = lines.last().map_or("", |(l, _)| l.as_str());
        if !last_line.eq_ignore_ascii_case("endif") {
            return Err(ParseError::InvalidLine {
                line: start_line,
                message: "条件块未闭合，缺少 'endif'".to_string(),
            });
        }

        let mut branches = Vec::new();
        let mut current_body_lines: Vec<(String, usize)> = Vec::new();
        let mut current_condition: Option<Expr> = None;
        let mut is_first = true;

        for (line, line_number) in lines {
            let trimmed = line.trim();

            if is_first {
                if !starts_with_ignore_case(trimmed, "if ") {
                    return Err(ParseError::InvalidLine {
                        line: *line_number,
                        message: "条件块必须以 'if' 开头".to_string(),
                    });
                }

                let condition_str = &trimmed[3..].trim();
                current_condition = Some(parse_expression(condition_str, *line_number)?);
                is_first = false;
                continue;
            }

            if starts_with_ignore_case(trimmed, "elseif ") {
                let body = self.parse_body_lines(&current_body_lines)?;
                branches.push(ConditionalBranch {
                    condition: current_condition.take(),
                    body,
                });
                current_body_lines.clear();

                let condition_str = &trimmed[7..].trim();
                current_condition = Some(parse_expression(condition_str, *line_number)?);
                continue;
            }

            if trimmed.eq_ignore_ascii_case("else") {
                let body = self.parse_body_lines(&current_body_lines)?;
                branches.push(ConditionalBranch {
                    condition: current_condition.take(),
                    body,
                });
                current_body_lines.clear();
                current_condition = None;
                continue;
            }

            if trimmed.eq_ignore_ascii_case("endif") {
                let body = self.parse_body_lines(&current_body_lines)?;
                branches.push(ConditionalBranch {
                    condition: current_condition.take(),
                    body,
                });
                break;
            }

            current_body_lines.push((trimmed.to_string(), *line_number));
        }

        if branches.is_empty() {
            return Err(ParseError::InvalidLine {
                line: start_line,
                message: "条件块没有有效分支".to_string(),
            });
        }

        Ok(Some(ScriptNode::Conditional { branches }))
    }

    /// 解析分支体内的行列表
    pub(super) fn parse_body_lines(
        &mut self,
        lines: &[(String, usize)],
    ) -> Result<Vec<ScriptNode>, ParseError> {
        let mut nodes = Vec::new();

        for (line, line_number) in lines {
            if line.trim().is_empty() {
                continue;
            }
            if let Some(node) = self.parse_single_line(line, *line_number)? {
                nodes.push(node);
            }
        }

        Ok(nodes)
    }

    /// 解析 goto 指令
    ///
    /// 语法: `goto label`
    pub(super) fn parse_goto(
        &self,
        line: &str,
        line_number: usize,
    ) -> Result<Option<ScriptNode>, ParseError> {
        let content = line
            .get(4..)
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .ok_or_else(|| ParseError::MissingParameter {
                line: line_number,
                command: "goto".to_string(),
                param: "目标标签".to_string(),
            })?;

        // 拒绝旧 **label** 语法
        if content.starts_with("**") && content.ends_with("**") && content.len() > 4 {
            let old_name = &content[2..content.len() - 2];
            return Err(ParseError::InvalidLine {
                line: line_number,
                message: format!("旧语法 goto **{old_name}** 已废弃，请使用 goto {old_name}"),
            });
        }

        let target_label = content.to_string();

        if target_label.is_empty() {
            return Err(ParseError::MissingParameter {
                line: line_number,
                command: "goto".to_string(),
                param: "目标标签".to_string(),
            });
        }

        if target_label.contains("::") {
            return Err(ParseError::InvalidLine {
                line: line_number,
                message: "暂不支持跨文件 goto，请使用 callScript/returnFromScript 组织流程"
                    .to_string(),
            });
        }

        Ok(Some(ScriptNode::Goto { target_label }))
    }

    /// 解析 callScript 指令
    ///
    /// 语法: `callScript "path/to/script.rks"`
    pub(super) fn parse_call_script(
        &self,
        line: &str,
        line_number: usize,
    ) -> Result<Option<ScriptNode>, ParseError> {
        let content = line
            .get("callScript".len()..)
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .ok_or_else(|| ParseError::MissingParameter {
                line: line_number,
                command: "callScript".to_string(),
                param: "目标脚本路径".to_string(),
            })?;

        // 拒绝旧 Markdown link 语法
        if content.starts_with('[') {
            return Err(ParseError::InvalidLine {
                line: line_number,
                message: "旧语法 callScript [label](path) 已废弃，请使用 callScript \"path\""
                    .to_string(),
            });
        }

        let path = extract_quoted_path(content).ok_or_else(|| ParseError::MissingParameter {
            line: line_number,
            command: "callScript".to_string(),
            param: "目标脚本路径 (\"path\")".to_string(),
        })?;

        Ok(Some(ScriptNode::CallScript {
            path: path.to_string(),
            display_label: None,
        }))
    }

    /// 解析 wait 指令
    ///
    /// 语法: `wait <duration> [nobreak]`，duration 为秒数（正数）。
    /// 携带 `nobreak` 时 skippable 为 false，玩家无法跳过此等待。
    pub(super) fn parse_wait(
        &self,
        line: &str,
        line_number: usize,
    ) -> Result<Option<ScriptNode>, ParseError> {
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() < 2 {
            return Err(ParseError::MissingParameter {
                line: line_number,
                command: "wait".to_string(),
                param: "等待时长（秒）".to_string(),
            });
        }

        let duration: f64 = parts[1].parse().map_err(|_| ParseError::InvalidParameter {
            line: line_number,
            param: "duration".to_string(),
            message: format!("无法解析为数字: '{}'", parts[1]),
        })?;

        if duration <= 0.0 {
            return Err(ParseError::InvalidParameter {
                line: line_number,
                param: "duration".to_string(),
                message: format!("等待时长必须为正数，实际: {duration}"),
            });
        }

        let skippable = !(parts.len() >= 3 && parts[2].eq_ignore_ascii_case("nobreak"));

        Ok(Some(ScriptNode::Wait {
            duration,
            skippable,
        }))
    }

    /// 解析表格块（选择分支）
    pub(super) fn parse_table(
        &mut self,
        lines: &[String],
        start_line: usize,
    ) -> Result<Option<ScriptNode>, ParseError> {
        if lines.is_empty() {
            return Ok(None);
        }

        let mut options = Vec::new();
        let mut style = None;
        let mut header_parsed = false;

        for (idx, line) in lines.iter().enumerate() {
            let line_number = start_line + idx;

            if is_table_separator(line) {
                continue;
            }

            let cells: Vec<&str> = line
                .split('|')
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .collect();

            if !header_parsed {
                if !cells.is_empty() {
                    style = Some(cells[0].to_string());
                }
                header_parsed = true;
                continue;
            }

            if cells.len() < 2 {
                self.warnings
                    .push(format!("第 {line_number} 行：表格行格式不完整，已跳过"));
                continue;
            }

            let target = cells[1].trim();
            if target.starts_with("**") && target.ends_with("**") && target.len() > 4 {
                let old_name = &target[2..target.len() - 2];
                return Err(ParseError::InvalidLine {
                    line: start_line,
                    message: format!(
                        "旧语法 **{old_name}** 已废弃，请在选择表格中直接使用标签名 {old_name}"
                    ),
                });
            }

            options.push(ChoiceOption {
                text: cells[0].to_string(),
                target_label: target.to_string(),
            });
        }

        if options.is_empty() {
            return Err(ParseError::InvalidTable {
                line: start_line,
                message: "表格中没有有效的选项".to_string(),
            });
        }

        Ok(Some(ScriptNode::Choice { style, options }))
    }
}

