80	/// 从字符串中提取第一个双引号包裹的路径
81	///
82	/// 输入: `changeBG "path/to/bg.png" with dissolve`
83	/// 输出: `Some("path/to/bg.png")`
84	pub fn extract_quoted_path(s: &str) -> Option<&str> {
85	    let start = s.find('"')?;
86	    let after_quote = &s[start + 1..];
87	    let end = after_quote.find('"')?;
88	    Some(&after_quote[..end])
89	}
90	
91	/// 查找关键字并提取其后的值
92	///
93	/// 输入: `"show <img> as royu at center with dissolve"`, `"as"`
94	/// 输出: `Some("royu")`
95	///
96	/// 支持多种格式：
97	/// - `... as value ...` (标准空格分隔)
98	/// - `...>as value ...` (无空格，紧跟 img 标签)
99	pub fn extract_keyword_value<'a>(s: &'a str, keyword: &str) -> Option<&'a str> {
100	    let lower = s.to_lowercase();
101	    let keyword_lower = keyword.to_lowercase();
102	
103	    // 尝试多种模式查找关键字
104	    let patterns = [
105	        format!(" {keyword_lower} "), // 标准：空格包围
106	        format!(">{keyword_lower} "), // 紧跟 >：如 />as
107	        format!(" {keyword_lower}"),  // 只有前空格
108	    ];
109	
110	    let mut best_pos = None;
111	    let mut best_pattern_len = 0;
112	
113	    for pattern in &patterns {
114	        if let Some(pos) = lower.find(pattern.as_str())
115	            && best_pos.is_none_or(|p| pos < p)
116	        {
117	            best_pos = Some(pos);
118	            best_pattern_len = pattern.len();
119	        }
120	    }
121	
122	    let pos = best_pos?;
123	    let value_start = pos + best_pattern_len;
124	
125	    // 确保 value_start 不超出范围
126	    if value_start >= s.len() {
127	        return None;
128	    }
129	
130	    let remaining = &s[value_start..];
131	    let remaining_lower = remaining.to_lowercase();
132	
133	    // 查找下一个关键字或边界的位置
134	    let terminators = [" with ", " as ", " at ", ">with", ">as", ">at"];
135	    let mut end_pos = remaining.len();
136	
137	    for term in &terminators {
138	        if let Some(p) = remaining_lower.find(term)
139	            && p < end_pos
140	        {
141	            end_pos = p;
142	        }
143	    }
144	
145	    let value = remaining[..end_pos].trim();
146	    if value.is_empty() { None } else { Some(value) }
147	}
148	
149	/// 解析过渡效果表达式
150	///
151	/// 输入: `"dissolve"` 或 `"Dissolve(1.5)"` 或 `"Dissolve(duration: 1.5)"`
152	pub fn parse_transition(s: &str) -> Option<Transition> {
153	    let s = s.trim();
154	    if s.is_empty() {
155	        return None;
156	    }
157	
158	    // 查找括号
159	    if let Some(paren_start) = s.find('(') {
160	        // 函数调用格式: name(args)
161	        let name = s[..paren_start].trim();
162	        let paren_end = s.rfind(')')?;
163	        let args_str = &s[paren_start + 1..paren_end];
164	
165	        match parse_transition_args(args_str) {
166	            Ok(args) => Some(Transition::with_named_args(name, args)),
167	            Err(_) => None, // 参数解析失败
168	        }
169	    } else {
170	        // 简单名称格式: name
171	        Some(Transition::simple(s))
172	    }
173	}
174	
175	/// 解析过渡效果参数列表（支持位置参数和命名参数，不允许混用）
176	///
177	/// - 位置参数: `1.0, 0.5, true, "x"`
178	/// - 命名参数: `duration: 1.0, reversed: true`
179	/// - 混用会返回 Err
180	pub fn parse_transition_args(s: &str) -> Result<Vec<(Option<String>, TransitionArg)>, String> {
181	    let s = s.trim();
182	    if s.is_empty() {
183	        return Ok(Vec::new());
184	    }
185	
186	    // 先分割参数（考虑字符串内的逗号）
187	    let raw_args = split_args(s);
188	    if raw_args.is_empty() {
189	        return Ok(Vec::new());
190	    }
191	
192	    let mut args = Vec::new();
193	    let mut has_named = false;
194	    let mut has_positional = false;
195	    let mut seen_keys = std::collections::HashSet::new();
196	
197	    for raw in &raw_args {
198	        let raw = raw.trim();
199	        if raw.is_empty() {
200	            continue;
201	        }
202	
203	        // 检测是否是命名参数（包含 key: value 模式）
204	        // 注意：字符串里的冒号不算
205	        if let Some((key, value)) = parse_named_arg(raw) {
206	            // 命名参数
207	            if has_positional {
208	                return Err("不允许混用位置参数和命名参数".to_string());
209	            }
210	            has_named = true;
211	
212	            // 检查重复 key
213	            if seen_keys.contains(&key) {
214	                return Err(format!("重复的命名参数: {key}"));
215	            }
216	            seen_keys.insert(key.clone());
217	
218	            args.push((Some(key), value));
219	        } else {
220	            // 位置参数
221	            if has_named {
222	                return Err("不允许混用位置参数和命名参数".to_string());
223	            }
224	            has_positional = true;
225	
226	            args.push((None, parse_arg_value(raw)));
227	        }
228	    }
229	
230	    Ok(args)
231	}
232	
233	/// 分割参数列表（考虑字符串内的逗号）
234	fn split_args(s: &str) -> Vec<String> {
235	    let mut result = Vec::new();
236	    let mut current = String::new();
237	    let mut in_string = false;
238	    let mut string_char = '"';
239	
240	    for ch in s.chars() {
241	        if in_string {
242	            current.push(ch);
243	            if ch == string_char {
244	                in_string = false;
245	            }
246	        } else if ch == '"' || ch == '\'' {
247	            in_string = true;
248	            string_char = ch;
249	            current.push(ch);
250	        } else if ch == ',' {
251	            result.push(current.trim().to_string());
252	            current.clear();
253	        } else {
254	            current.push(ch);
255	        }
256	    }
257	
258	    // 最后一个参数
259	    let last = current.trim();
260	    if !last.is_empty() {
261	        result.push(last.to_string());
262	    }
263	
264	    result
265	}
266	
267	/// 尝试解析命名参数 "key: value"
268	/// 返回 Some((key, value)) 或 None（如果不是命名参数）
269	fn parse_named_arg(s: &str) -> Option<(String, TransitionArg)> {
270	    // 查找第一个不在字符串内的冒号
271	    let mut in_string = false;
272	    let mut string_char = '"';
273	    let mut colon_pos = None;
274	
275	    for (i, ch) in s.char_indices() {
276	        if in_string {
277	            if ch == string_char {
278	                in_string = false;
279	            }
280	        } else if ch == '"' || ch == '\'' {
281	            in_string = true;
282	            string_char = ch;
283	        } else if ch == ':' {
284	            colon_pos = Some(i);
285	            break;
286	        }
287	    }
288	
289	    let colon_pos = colon_pos?;
290	    let key = s[..colon_pos].trim();
291	    let value_str = s[colon_pos + 1..].trim();
292	
293	    // key 必须是有效标识符 [a-zA-Z_][a-zA-Z0-9_]*
294	    if !is_valid_identifier(key) {
295	        return None;
296	    }
297	
298	    // 解析 value
299	    let value = parse_arg_value(value_str);
300	    Some((key.to_string(), value))
301	}
302	
303	/// 检查是否是有效标识符
304	fn is_valid_identifier(s: &str) -> bool {
305	    if s.is_empty() {
306	        return false;
307	    }
308	    let mut chars = s.chars();
309	    let first = chars
310	        .next()
311	        .expect("invariant: non-empty string already checked");
312	    if !first.is_ascii_alphabetic() && first != '_' {
313	        return false;
314	    }
315	    chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
316	}
317	
318	/// 解析参数值（可能带引号的字符串、数字、布尔值）
319	pub fn parse_arg_value(s: &str) -> TransitionArg {
320	    let s = s.trim();
321	
322	    // 带引号的字符串
323	    if ((s.starts_with('"') && s.ends_with('"')) || (s.starts_with('\'') && s.ends_with('\'')))
324	        && s.len() >= 2
325	    {
326	        return TransitionArg::String(s[1..s.len() - 1].to_string());
327	    }
328	
329	    parse_single_arg(s)
330	}
331	
332	/// 解析单个参数值
333	fn parse_single_arg(s: &str) -> TransitionArg {
334	    let s = s.trim();
335	
336	    // 尝试解析为数字
337	    if let Ok(n) = s.parse::<f64>() {
338	        return TransitionArg::Number(n);
339	    }
340	
341	    // 尝试解析为布尔值
342	    if s.eq_ignore_ascii_case("true") {
343	        return TransitionArg::Bool(true);
344	    }
345	    if s.eq_ignore_ascii_case("false") {
346	        return TransitionArg::Bool(false);
347	    }
348	
349	    // 作为字符串处理
350	    TransitionArg::String(s.to_string())
351	}
352	
353	/// 检查是否是表格分隔行 (| --- | --- |)
354	pub fn is_table_separator(s: &str) -> bool {
355	    let s = s.trim();
356	    if !s.starts_with('|') || !s.ends_with('|') {
357	        return false;
358	    }
359	
360	    // 检查中间只包含 -, :, |, 空格
361	    s[1..s.len() - 1]
362	        .chars()
363	        .all(|c| c == '-' || c == ':' || c == '|' || c.is_whitespace())
364	}
365	
366	/// 解析对话行，提取说话者和内容
367	///
368	/// 支持格式:
369	/// - `角色名："内容"` 或 `角色名："内容"`
370	/// - `角色名: "内容"` 或 `角色名: "内容"`
371	/// - `："内容"` (旁白)
372	pub fn parse_dialogue(s: &str) -> Option<(Option<String>, String)> {
373	    let s = s.trim();
374	
375	    // 查找冒号位置（支持中英文冒号）
376	    // 中文冒号 U+FF1A (：) 或 U+003A (:)
377	    let (colon_pos, colon_len) = if let Some(pos) = s.find('：') {
378	        (pos, '：'.len_utf8())
379	    } else {
380	        let pos = s.find(':')?;
381	        (pos, ':'.len_utf8())
382	    };
383	
384	    let speaker_part = s[..colon_pos].trim();
385	    let content_part = s[colon_pos + colon_len..].trim();
386	
387	    // 内容必须被引号包围
388	    let content = extract_quoted_content(content_part)?;
389	
390	    let speaker = if speaker_part.is_empty() {
391	        None
392	    } else {
393	        Some(speaker_part.to_string())
394	    };
395	
396	    Some((speaker, content.to_string()))
397	}
398	
399	/// 提取引号内的内容
400	///
401	/// 支持:
402	/// - "内容" (ASCII 双引号 U+0022)
403	/// - "内容" (中文引号 U+201C / U+201D)
404	pub(crate) fn extract_quoted_content(s: &str) -> Option<&str> {
405	    // 定义引号字符
406	    const ASCII_QUOTE: char = '"'; // U+0022
407	    const CN_LEFT_QUOTE: char = '\u{201C}'; // 中文左双引号
408	    const CN_RIGHT_QUOTE: char = '\u{201D}'; // 中文右双引号
409	
410	    let s = s.trim();
411	
412	    // 获取第一个字符
413	    let first_char = s.chars().next()?;
414	
415	    // 确定开始和结束引号
416	    let end_quote = if first_char == ASCII_QUOTE {
417	        ASCII_QUOTE
418	    } else if first_char == CN_LEFT_QUOTE {
419	        CN_RIGHT_QUOTE
420	    } else {
421	        return None;
422	    };
423	
424	    // 跳过开始引号
425	    let content_start = first_char.len_utf8();
426	    let remaining = &s[content_start..];
427	
428	    // 查找结束引号
429	    let end_pos = remaining.find(end_quote)?;
430	
431	    Some(&remaining[..end_pos])
432	}
433

