        assert_eq!(effects[1].kind, InlineEffectKind::SetCpsRelative(2.0));
        assert_eq!(effects[2].kind, InlineEffectKind::ResetCps);
    }

    #[test]
    fn empty_input() {
        let (text, effects) = parse_inline_tags("");
        assert_eq!(text, "");
