92	///
93	/// 输入: `"show <img> as royu at center with dissolve"`, `"as"`
94	/// 输出: `Some("royu")`
95	///
96	/// 支持多种格式：
97	/// - `... as value ...` (标准空格分隔)
98	/// - `...>as value ...` (无空格，紧跟 img 标签)
99	pub fn extract_keyword_value<'a>(s: &'a str, keyword: &str) -> Option<&'a str> {
100	    let lower = s.to_lowercase();
101	    let keyword_lower = keyword.to_lowercase();
102	
103	    // 尝试多种模式查找关键字
104	    let patterns = [
105	        format!(" {keyword_lower} "), // 标准：空格包围
106	        format!(">{keyword_lower} "), // 紧跟 >：如 />as
107	        format!(" {keyword_lower}"),  // 只有前空格
108	    ];
109	
110	    let mut best_pos = None;
111	    let mut best_pattern_len = 0;
112	
113	    for pattern in &patterns {
114	        if let Some(pos) = lower.find(pattern.as_str())
115	            && best_pos.is_none_or(|p| pos < p)
116	        {
117	            best_pos = Some(pos);
118	            best_pattern_len = pattern.len();
119	        }
120	    }
121	
122	    let pos = best_pos?;
123	    let value_start = pos + best_pattern_len;
124	
125	    // 确保 value_start 不超出范围
126	    if value_start >= s.len() {
127	        return None;
128	    }
129	
130	    let remaining = &s[value_start..];
131	    let remaining_lower = remaining.to_lowercase();
132	
133	    // 查找下一个关键字或边界的位置
134	    let terminators = [" with ", " as ", " at ", ">with", ">as", ">at"];
135	    let mut end_pos = remaining.len();
136	
137	    for term in &terminators {
138	        if let Some(p) = remaining_lower.find(term)
139	            && p < end_pos
140	        {
141	            end_pos = p;
142	        }
143	    }
144	
145	    let value = remaining[..end_pos].trim();
146	    if value.is_empty() { None } else { Some(value) }
147	}

