//! # 辅助解析函数
//!
//! 手写的字符串解析辅助函数，无正则依赖。

use crate::command::{Transition, TransitionArg};

/// 跳过字符串开头的空白字符，返回剩余部分
pub(crate) fn skip_whitespace(s: &str) -> &str {
    s.trim_start()
}

/// 检查字符串是否以指定前缀开头（大小写不敏感）
pub fn starts_with_ignore_case(s: &str, prefix: &str) -> bool {
    s.len() >= prefix.len()
        && s.chars()
            .zip(prefix.chars())
            .all(|(a, b)| a.eq_ignore_ascii_case(&b))
}

