    fn parse_rule_function(&self, text: &str) -> Option<Transition> {
        let inner_start = text.find('(')?;
        let inner_end = text.rfind(')')?;
        if inner_start >= inner_end {
            return None;
        }
        let inner = &text[inner_start + 1..inner_end];

        // 第一个参数是遮罩路径（引号包裹）
        let mask_path = extract_quoted_path(inner)?;

        let mut args = vec![(
            Some("mask".to_string()),
            TransitionArg::String(mask_path.to_string()),
        )];

        // 找到引号路径的结束位置，提取后续参数
        let first_quote = inner.find('"')?;
        let after_first = &inner[first_quote + 1..];
        let close_quote = after_first.find('"')?;
        let remaining = &after_first[close_quote + 1..];
        let remaining = remaining.trim_start().strip_prefix(',').unwrap_or("");

        if !remaining.trim().is_empty()
            && let Ok(extra_args) = parse_transition_args(remaining.trim())
        {
            args.extend(extra_args);
        }

        Some(Transition::with_named_args("rule", args))
    }
