+/// 在原始字符串中查找 ASCII 模式（大小写不敏感），返回原始字符串的字节位置。
+///
+/// 与 `s.to_lowercase().find(pattern)` 不同，返回的位置对 `s` 有效，
+/// 不会因 Unicode 大小写映射改变字节长度而错位。
+pub(crate) fn find_ascii_ci(s: &str, pattern: &str) -> Option<usize> {
+    let s_bytes = s.as_bytes();
+    let p_bytes = pattern.as_bytes();
+    if p_bytes.len() > s_bytes.len() {
+        return None;
+    }
+    for i in 0..=(s_bytes.len() - p_bytes.len()) {
+        if s_bytes[i..i + p_bytes.len()]
+            .iter()
+            .zip(p_bytes)
+            .all(|(a, b)| a.eq_ignore_ascii_case(b))
+        {
+            return Some(i);
+        }
+    }
+    None
+}
+
+/// `find_ascii_ci` 的反向搜索版本
+pub(crate) fn rfind_ascii_ci(s: &str, pattern: &str) -> Option<usize> {
+    let s_bytes = s.as_bytes();
+    let p_bytes = pattern.as_bytes();
+    if p_bytes.len() > s_bytes.len() {
+        return None;
+    }
+    for i in (0..=(s_bytes.len() - p_bytes.len())).rev() {
+        if s_bytes[i..i + p_bytes.len()]
+            .iter()
+            .zip(p_bytes)
+            .all(|(a, b)| a.eq_ignore_ascii_case(b))
+        {
+            return Some(i);
+        }
+    }
+    None
+}
